WITH gated AS (SELECT model FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' GROUP BY model HAVING count() >= 100) SELECT round(quantile(0.5)(ttft_content_ms)) AS "TTFT p50 (ms)", round(quantile(0.95)(ttft_content_ms)) AS "TTFT p95 (ms)", round(countIf(ttft_content_ms <= 2000) * 100.0 / count(), 1) AS "Goodput <=2s (%)" FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND is_stream = 1 AND ttft_content_ms > 0 AND coalesce(nullIf(key_id,''), nullIf(api_key_id,''), 'unknown') IN ({{ gf_str_multi('api_key') }}) AND model IN ({{ gf_str_multi('model') }}) AND model IN (SELECT model FROM gated)
